# ИИ-черновик (D-25): английские глаголы, топ-100. f = (s, past, participle, ing); модальные — без форм.
def E(tr, f, ex1, ex2, pair=None, irr=False, note=None):
    d = dict(tr=tr, ex=[ex1, ex2])
    if f:
        d['F'] = dict(zip(('s', 'past', 'participle', 'ing'), f))
    if irr: d['irr'] = 1
    if pair: d['pair'] = 'es:' + pair
    if note: d['note'] = note
    return d

